            if(best<0 && contacts.length<8){best=contacts.length;contacts.push({x:p[0],y:p[1],tx:p[0],ty:p[1],ax:p[0],ay:p[1],mx:p[0],my:p[1],markAt:elapsed,dx:0,dy:0,age:0,a:0,last:now});}
